const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const dir = fs.mkdtempSync("/tmp/proj-");
fs.writeFileSync(path.join(dir, "index.js"), "export default { fetch() { return new Response('ok'); } };\n");
fs.writeFileSync(path.join(dir, "wrangler.json"), JSON.stringify({ name: "w", main: "index.js", compatibility_date: "2025-01-01" }));
const r = spawnSync(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "check", "startup"], {
  cwd: dir, encoding: "utf8", timeout: 75000,
  env: Object.assign({}, process.env, { CI: "1", WRANGLER_SEND_METRICS: "false", NO_COLOR: "1", FORCE_COLOR: "0" })
});
if (r.error) broken("could not run wrangler check startup: " + r.error.message);
const out = (r.stdout || "") + (r.stderr || "");
if (!/wrangler \d+\.\d+\.\d+/.test(out)) broken("wrangler check startup did not print the wrangler banner: " + out.slice(0, 500));
if (out.includes("`wrangler check startup` is an alpha command")) symptom("wrangler check startup prints an alpha command warning");
console.log("OK: wrangler check startup prints no alpha warning");

